/** Stopwords padrão (português), comparadas após a mesma normalização dos termos. */
export const DEFAULT_STOPWORDS = Object.freeze([
  'a', 'o', 'as', 'os', 'de', 'da', 'do', 'das', 'dos', 'e', 'é', 'em', 'no', 'na', 'nos', 'nas',
