    }
    // Grupo de opções curtas: `-abc` = `-a -b -c`; só a última pode receber valor.
    const letters = [...tok.slice(1)];
    for (const letter of letters.slice(0, -1)) set(canon(letter), true);
    i = takeOption(letters[letters.length - 1], i);
